# shape signature of each 3x3 block (pattern of nonzero relative positions + color)
def sig(block):
    cells=frozenset((r,c) for r in range(3) for c in range(3) if block[r][c])
    col=next(block[r][c] for r in range(3) for c in range(3) if block[r][c])
    return (col,cells)

