import json
RULE={1:((0,1),3), 2:((0,-1),2), 6:((1,0),2), 3:((0,-1),4)}
def transform(grid):
    H=len(grid)
    out=[[0]*7 for _ in range(H)]
    r5=c5=None
    for r in range(H):
        for c in range(8,15):
            if grid[r][c]==5: r5,c5=r,c-8
    out[r5][c5]=5
    shapes=[]
    for b in range((H+1)//4):
        r0=4*b
        if r0+3>H: break
        for c0,side in [(0,'L'),(4,'R')]:
            blk=[[grid[r0+i][c0+j] for j in range(3)] for i in range(3)]
            if any(any(row) for row in blk):
                col=next(x for row in blk for x in row if x)
                shapes.append((side,r0,col))
    order=[s for s in shapes if s[0]=='L']+sorted([s for s in shapes if s[0]=='R'],key=lambda s:s[1])
    r,c=r5+1,c5
    for side,r0,col in order:
        (dr,dc),ln=RULE[col]
        for k in range(ln):
            rr,cc=r+k*dr,c+k*dc
            out[rr][cc]=col
        r,c=r+(ln-1)*dr+1, c+(ln-1)*dc
    return out

